using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerDependencyTests
{
    private const string DomainNs = "PaymentAuthorization.Domain";
    private const string ApplicationNs = "PaymentAuthorization.Application";
    private const string InfrastructureNs = "PaymentAuthorization.Infrastructure";

    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
    ];

    private static readonly System.Reflection.Assembly DomainAssembly = typeof(Money).Assembly;
    private static readonly System.Reflection.Assembly ApplicationAssembly = typeof(AuthorizePayment).Assembly;
    private static readonly System.Reflection.Assembly InfrastructureAssembly = typeof(HttpPaymentGateway).Assembly;

    [Fact]
    public void Domain_does_not_depend_on_outer_layers() =>
        AssertNoDependency(DomainAssembly, ApplicationNs, InfrastructureNs);

    [Fact]
    public void Application_does_not_depend_on_infrastructure() =>
        AssertNoDependency(ApplicationAssembly, InfrastructureNs);

    [Fact]
    public void Domain_does_not_use_technical_details() =>
        AssertNoDependency(DomainAssembly, TechnicalNamespaces);

    [Fact]
    public void Application_does_not_use_technical_details() =>
        AssertNoDependency(ApplicationAssembly, TechnicalNamespaces);

    [Fact]
    public void Infrastructure_is_the_layer_that_holds_the_technical_details()
    {
        var result = Types.InAssembly(InfrastructureAssembly).That().ResideInNamespace(InfrastructureNs)
            .Should().HaveDependencyOnAny(TechnicalNamespaces).GetResult();
        Assert.True(result.IsSuccessful);
    }

    private static void AssertNoDependency(System.Reflection.Assembly assembly, params string[] forbidden)
    {
        var result = Types.InAssembly(assembly).ShouldNot().HaveDependencyOnAny(forbidden).GetResult();
        Assert.True(result.IsSuccessful, "Forbidden dependencies in: " + string.Join(", ", result.FailingTypeNames ?? []));
    }
}
